<script>document.querySelectorAll('[data-toggle-password]').forEach(button => button.addEventListener('click', () => { const input = document.getElementById(button.dataset.togglePassword); const visible = input.type === 'text'; input.type = visible ? 'password' : 'text'; button.textContent = visible ? '👁' : '🙈'; button.setAttribute('aria-label', visible ? 'Tampilkan kata sandi' : 'Sembunyikan kata sandi'); }));</script>
